const http = require("http");
const { URL } = require("url");

function fib(n) {
  let a = 0n, b = 1n;
  for (let i = 0; i < n; i++) {
    [a, b] = [b, a + b];
  }
  return a;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://localhost:3000");

  if (req.method !== "GET" || url.pathname !== "/fib") {
    res.statusCode = 404;
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({ error: "Not Found" }));
    return;
  }

  const nParam = url.searchParams.get("n");
  if (nParam === null) {
    res.statusCode = 400;
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({ error: "Missing query parameter n" }));
    return;
  }

  if (!/^-?\d+$/.test(nParam)) {
    res.statusCode = 400;
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({ error: "Query parameter n must be an integer" }));
    return;
  }

  const n = Number(nParam);
  if (!Number.isSafeInteger(n) || n < 0) {
    res.statusCode = 400;
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({ error: "Query parameter n must be a non-negative safe integer" }));
    return;
  }

  const result = fib(n).toString();
  res.statusCode = 200;
  res.setHeader("Content-Type", "application/json");
  res.end(JSON.stringify({ result }));
});

server.listen(3000, "0.0.0.0");
EOF
