import os, pty, subprocess, select, time, re
from collections import deque

OUTDIR="/app/output"
os.makedirs(OUTDIR, exist_ok=True)

DIRS={"N":(0,-1),"S":(0,1),"E":(1,0),"W":(-1,0)}
OPP={"N":"S","S":"N","E":"W","W":"E"}
ORDER=["N","E","S","W"]

class Game:
    def __init__(self, maze_id):
        self.maze_id=str(maze_id)
        self.pid, self.fd = pty.fork()
        if self.pid==0:
            os.execvp("./maze_game.sh", ["./maze_game.sh", self.maze_id])
        time.sleep(0.05)
    def cmd(self, s):
        os.write(self.fd, (s+"\n").encode())
        data=b""
        while True:
            r,_,_=select.select([self.fd],[],[],1)
            if not r:
                break
            chunk=os.read(self.fd,4096)
            if not chunk:
                break
            data+=chunk
            if b"\n" in data:
                break
        txt=data.decode(errors="ignore")
        lines=[ln for ln in txt.replace("\r","").split("\n") if ln.strip()]
        return lines[-1].strip() if lines else ""
    def close(self):
        try: os.close(self.fd)
        except: pass

for maze_id in range(1,11):
    g=Game(maze_id)
    pos=(0,0)
    start=pos
    exit_pos=None
    open_cells={start}
    walls=set()
    visited=set()

    def move_path(path):
        nonlocal_pos=[pos]
        cur=nonlocal_pos[0]
        if not path:
            return cur
        resp=g.cmd("move "+" & ".join(path))
        parts=[p.strip() for p in resp.split("&")]
        for d,res in zip(path,parts):
            dx,dy=DIRS[d]
            if res=="moved" or res=="reached exit":
                cur=(cur[0]+dx, cur[1]+dy)
                open_cells.add(cur)
                if res=="reached exit":
                    exit_pos=cur
            elif res=="hit wall":
                walls.add((cur[0]+dx, cur[1]+dy))
            else:
                raise RuntimeError((maze_id,path,resp))
        return cur, resp

    pos=(0,0)
    parent={start:None}
    stack=[start]
    path_to={start:[]}

    while stack:
        target=stack.pop()
        path=path_to[target]
        if pos!=target:
            pos,_=move_path(path)
        if target in visited:
            continue
        visited.add(target)
        for d in ORDER:
            dx,dy=DIRS[d]
            nxt=(target[0]+dx,target[1]+dy)
            if nxt in open_cells or nxt in walls:
                continue
            old=pos
            pos,resp=move_path([d])
            res=resp.strip()
            if res=="hit wall":
                pos=old
            else:
                if nxt not in path_to:
                    path_to[nxt]=path+[d]
                back=OPP[d]
                pos,_=move_path([back])
                stack.append(nxt)

    xs=[p[0] for p in open_cells|walls]
    ys=[p[1] for p in open_cells|walls]
    minx,maxx=min(xs),max(xs)
    miny,maxy=min(ys),max(ys)
    rows=[]
    for y in range(miny,maxy+1):
        row=[]
        for x in range(minx,maxx+1):
            p=(x,y)
            if p==start: row.append("S")
            elif p==exit_pos: row.append("E")
            elif p in open_cells: row.append(" ")
            else: row.append("#")
        rows.append("".join(row))
    with open(f"{OUTDIR}/{maze_id}.txt","w") as f:
        f.write("\n".join(rows)+"\n")
    g.close()
print("done")
