    if 'conversations' in ex:
        text = stringify(ex['conversations'])
    elif 'messages' in ex:
        text = stringify(ex['messages'])
    elif 'text' in ex:
        text = stringify(ex['text'])
    else:
        text = '\n'.join(stringify(ex[f]) for f in text_fields if f != domain_col)
    count += len(tok.encode(text, add_special_tokens=False))

