import os
import socket
from flask import Flask, jsonify
from bitcoinlib.services.services import Service

app = Flask(__name__)

BTC_RPC_HOST = os.getenv("BTC_RPC_HOST", "127.0.0.1")
BTC_RPC_PORT = int(os.getenv("BTC_RPC_PORT", "8332"))
BTC_RPC_USER = os.getenv("BTC_RPC_USER", "")
BTC_RPC_PASSWORD = os.getenv("BTC_RPC_PASSWORD", "")
P2P_HOST = os.getenv("BTC_P2P_HOST", "127.0.0.1")
P2P_PORT = int(os.getenv("BTC_P2P_PORT", "8333"))


def p2p_reachable(host=P2P_HOST, port=P2P_PORT, timeout=2):
    try:
        with socket.create_connection((host, port), timeout=timeout):
            return True
    except OSError:
        return False


def rpc_client():
    if not (BTC_RPC_USER and BTC_RPC_PASSWORD):
        return None
    return Service(network="bitcoin", providers=["bitcoind"],
                   base_url=f"http://{BTC_RPC_USER}:{BTC_RPC_PASSWORD}@{BTC_RPC_HOST}:{BTC_RPC_PORT}")


def rpc_call(method, *params):
    client = rpc_client()
    if client is None:
        raise ConnectionError("Bitcoin Core RPC credentials are not configured")
    provider = client.providers[0]
    if hasattr(provider, "proxy"):
        func = getattr(provider.proxy, method)
        return func(*params)
    raise ConnectionError("Bitcoin Core RPC provider unavailable")


@app.route("/status")
def status():
    if not p2p_reachable():
        return jsonify({"status": "not connected to Bitcoin network on port 8333"}), 503
    try:
        info = rpc_call("getblockchaininfo")
        if isinstance(info, dict):
            return jsonify({"status": "online"})
    except Exception as e:
        return jsonify({"status": str(e)}), 503
    return jsonify({"status": "online"})


@app.route("/block/<block_hash>")
def get_block(block_hash):
    if not p2p_reachable():
        return jsonify({"error": "not connected to Bitcoin network"}), 503
    try:
        block = rpc_call("getblock", block_hash)
        return jsonify({
            "hash": block.get("hash"),
            "height": block.get("height"),
            "merkleroot": block.get("merkleroot"),
            "time": block.get("time"),
            "nonce": block.get("nonce"),
            "tx": block.get("tx", []),
        })
    except Exception:
        return jsonify({"error": "block not found"}), 404


@app.route("/transaction/<txid>")
def get_transaction(txid):
    if not p2p_reachable():
        return jsonify({"error": "not connected to Bitcoin network"}), 503
    try:
        tx = rpc_call("getrawtransaction", txid, True)
        vin = [
            {
                "coinbase": entry.get("coinbase", ""),
                "sequence": entry.get("sequence")
            }
            for entry in tx.get("vin", [])
        ]
        vout = [
            {
                "value": entry.get("value"),
                "n": entry.get("n"),
                "scriptPubKey": {
                    "asm": entry.get("scriptPubKey", {}).get("asm", ""),
                    "hex": entry.get("scriptPubKey", {}).get("hex", ""),
                    "type": entry.get("scriptPubKey", {}).get("type", "")
                }
            }
            for entry in tx.get("vout", [])
        ]
        return jsonify({
            "txid": tx.get("txid"),
            "blockhash": tx.get("blockhash", ""),
            "vin": vin,
            "vout": vout,
        })
    except Exception:
        return jsonify({"error": "transaction not found"}), 404


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000)
