import os, subprocess, collections
from pathlib import Path

base=Path('/app')
outdir=base/'output'
outdir.mkdir(exist_ok=True)

DIRS={'N':(0,-1),'S':(0,1),'E':(1,0),'W':(-1,0)}
OPP={'N':'S','S':'N','E':'W','W':'E'}
ORDER=['N','E','S','W']

class MazeProc:
    def __init__(self, maze_id):
        self.p=subprocess.Popen([str(base/'maze_game.sh'), str(maze_id)], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, bufsize=1)
    def move(self, d):
        self.p.stdin.write(f'move {d}\n'); self.p.stdin.flush()
        return self.p.stdout.readline().strip()
    def close(self):
        try:
            self.p.stdin.close()
        except Exception:
            pass
        try:
            self.p.terminate(); self.p.wait(timeout=1)
        except Exception:
            try: self.p.kill()
            except Exception: pass

def solve(mid):
    mp={(0,0):'S'}
    pos=(0,0)
    exit_pos=None
    stack=[(0,0,0)]
    # iterative DFS exploring all reachable cells, maintaining actual process position = stack top coord
    proc=MazeProc(mid)
    visited={(0,0)}
    try:
        while stack:
            x,y,i=stack[-1]
            if i>=4:
                stack.pop()
                if stack:
                    px,py,_=stack[-1]
                    dx,dy=px-x,py-y
                    back = 'N' if (dx,dy)==(0,-1) else 'S' if (dx,dy)==(0,1) else 'E' if (dx,dy)==(1,0) else 'W'
                    r=proc.move(back)
                    if r not in ('moved','reached exit'):
                        raise RuntimeError(f'backtrack failed maze {mid} from {(x,y)} to {(px,py)}: {r}')
                continue
            d=ORDER[i]
            stack[-1]=(x,y,i+1)
            dx,dy=DIRS[d]
            nx,ny=x+dx,y+dy
            if (nx,ny) in mp:
                continue
            r=proc.move(d)
            if r=='hit wall':
                mp[(nx,ny)]='#'
            elif r in ('moved','reached exit'):
                if r=='reached exit':
                    exit_pos=(nx,ny)
                if (nx,ny) not in visited:
                    visited.add((nx,ny))
                    mp[(nx,ny)]=' '
                    stack.append((nx,ny,0))
                else:
                    # should not happen because unknown cells only, but backtrack immediately if does
                    rr=proc.move(OPP[d])
                    if rr not in ('moved','reached exit'):
                        raise RuntimeError(f'return failed {mid}')
            else:
                raise RuntimeError(f'unexpected response {r!r} maze {mid}')
    finally:
        proc.close()
    if exit_pos is None:
        raise RuntimeError(f'no exit found in maze {mid}')
    mp[exit_pos]='E'
    mp[(0,0)]='S'
    xs=[x for x,y in mp]
    ys=[y for x,y in mp]
    minx,maxx,miny,maxy=min(xs),max(xs),min(ys),max(ys)
    rows=[]
    for y in range(miny,maxy+1):
        row=[]
        for x in range(minx,maxx+1):
            row.append(mp.get((x,y),'#'))
        rows.append(''.join(row))
    (outdir/f'{mid}.txt').write_text('\n'.join(rows)+'\n')

for mid in range(1,11):
    solve(mid)
print('done')
