import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist


def _get_rank_world():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank(), dist.get_world_size()
    return 0, 1


class _GatherConcat(torch.autograd.Function):
    @staticmethod
    def forward(ctx, local_out):
        rank, world_size = _get_rank_world()
        ctx.world_size = world_size
        ctx.rank = rank
        if world_size == 1:
            return local_out
        parts = [torch.empty_like(local_out) for _ in range(world_size)]
        dist.all_gather(parts, local_out)
        return torch.cat(parts, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        if ctx.world_size == 1:
            return grad_output
        chunk = grad_output.size(-1) // ctx.world_size
        start = ctx.rank * chunk
        end = start + chunk
        return grad_output[..., start:end]


class _AllReduceSum(torch.autograd.Function):
    @staticmethod
    def forward(ctx, local_out):
        rank, world_size = _get_rank_world()
        ctx.world_size = world_size
        if world_size == 1:
            return local_out
        out = local_out.clone()
        dist.all_reduce(out)
        return out

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        rank, world_size = _get_rank_world()
        if out_features % world_size != 0:
            raise ValueError('out_features must be divisible by world_size')
        self.in_features = in_features
        self.out_features = out_features
        self.output_size_per_rank = out_features // world_size
        start = rank * self.output_size_per_rank
        end = start + self.output_size_per_rank
        local_weight = master_weight[start:end, :].contiguous()
        self.weight = nn.Parameter(local_weight)
        if bias:
            self.bias = nn.Parameter(torch.zeros(self.output_size_per_rank, dtype=master_weight.dtype, device=master_weight.device))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        local_out = F.linear(input, self.weight, self.bias)
        return _GatherConcat.apply(local_out)


class RowParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        rank, world_size = _get_rank_world()
        if in_features % world_size != 0:
            raise ValueError('in_features must be divisible by world_size')
        self.in_features = in_features
        self.out_features = out_features
        self.input_size_per_rank = in_features // world_size
        start = rank * self.input_size_per_rank
        end = start + self.input_size_per_rank
        local_weight = master_weight[:, start:end].contiguous()
        self.weight = nn.Parameter(local_weight)
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_features, dtype=master_weight.dtype, device=master_weight.device))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        rank, world_size = _get_rank_world()
        if world_size == 1:
            local_input = input
        else:
            if input.size(-1) == self.input_size_per_rank:
                local_input = input
            else:
                start = rank * self.input_size_per_rank
                end = start + self.input_size_per_rank
                local_input = input[..., start:end]
        local_out = F.linear(local_input, self.weight, None)
        out = _AllReduceSum.apply(local_out)
        if self.bias is not None:
            out = out + self.bias
        return out
