import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist


def _get_dist_info():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size(), dist.get_rank()
    return 1, 0


class _AllGatherConcat(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        world_size, rank = _get_dist_info()
        ctx.world_size = world_size
        ctx.rank = rank
        if world_size == 1:
            return x
        outputs = [torch.empty_like(x) for _ in range(world_size)]
        dist.all_gather(outputs, x)
        return torch.cat(outputs, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        if ctx.world_size == 1:
            return grad_output
        chunks = torch.chunk(grad_output, ctx.world_size, dim=-1)
        return chunks[ctx.rank].contiguous()


class _AllReduceSum(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        world_size, _ = _get_dist_info()
        ctx.world_size = world_size
        if world_size == 1:
            return x
        y = x.clone()
        dist.all_reduce(y)
        return y

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        world_size, rank = _get_dist_info()
        if out_features % world_size != 0:
            raise ValueError('out_features must be divisible by world_size')
        self.in_features = in_features
        self.out_features = out_features
        self.local_out_features = out_features // world_size
        self.rank = rank
        self.world_size = world_size

        weight_chunks = torch.chunk(master_weight, world_size, dim=0)
        local_weight = weight_chunks[rank].contiguous()
        self.weight = nn.Parameter(local_weight)

        if bias:
            self.bias = nn.Parameter(torch.zeros(self.local_out_features, device=master_weight.device, dtype=master_weight.dtype))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        local_output = F.linear(input, self.weight, self.bias)
        return _AllGatherConcat.apply(local_output)


class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        world_size, rank = _get_dist_info()
        if in_features % world_size != 0:
            raise ValueError('in_features must be divisible by world_size')
        self.in_features = in_features
        self.out_features = out_features
        self.local_in_features = in_features // world_size
        self.rank = rank
        self.world_size = world_size

        weight_chunks = torch.chunk(master_weight, world_size, dim=1)
        local_weight = weight_chunks[rank].contiguous()
        self.weight = nn.Parameter(local_weight)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_features, device=master_weight.device, dtype=master_weight.dtype))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        input_chunks = torch.chunk(input, self.world_size, dim=-1)
        local_input = input_chunks[self.rank].contiguous()
        partial = F.linear(local_input, self.weight, None)
        output = _AllReduceSum.apply(partial)
        if self.bias is not None:
            output = output + self.bias
        return output
