import pandas as pd, numpy as np
from itertools import combinations
from sklearn.linear_model import LinearRegression
from pathlib import Path

csv=Path('/app/bn_sample_10k.csv')
df=pd.read_csv(csv)
cols=list(df.columns)

# score directed edge a->b by reduction in residual variance predicting b from a
scores=[]
for a,b in combinations(cols,2):
    for parent,child in [(a,b),(b,a)]:
        X=df[[parent]].values; y=df[child].values
        m=LinearRegression().fit(X,y)
        resid=y-m.predict(X)
        s=np.var(resid)
        scores.append((s,parent,child,m.coef_[0],m.intercept_))

# Greedy choose 6 edges with unique directed pairs, preferring low residual variance, enforcing U has no parents
edges=[]
parents={c:set() for c in cols}
children={c:set() for c in cols}
for s,parent,child,coef,inter in sorted(scores,key=lambda t:t[0]):
    if child=='U':
        continue
    if (parent,child) in edges or (child,parent) in edges:
        continue
    # avoid cycles
    def reaches(x,y,seen=None):
        if seen is None: seen=set()
        if x==y: return True
        seen.add(x)
        return any(n not in seen and reaches(n,y,seen) for n in children[x])
    if reaches(child,parent):
        continue
    edges.append((parent,child,coef,inter))
    parents[child].add(parent); children[parent].add(child)
    if len(edges)==6:
        break

# If greedy insufficient or dubious, refine via pairwise corr and alphabet rule for unclear orientation.
# Fit linear Gaussian BN parameters using recovered DAG.
edge_pairs=[(p,c) for p,c,_,_ in edges]
learned=pd.DataFrame({'to':[c for p,c in edge_pairs],'from':[p for p,c in edge_pairs]})
learned.to_csv('/app/learned_dag.csv',index=False)

params={}
for node in cols:
    ps=[p for p,c in edge_pairs if c==node]
    if ps:
        X=df[ps].values; y=df[node].values
        m=LinearRegression().fit(X,y)
        resid=y-m.predict(X)
        params[node]=('lin',ps,m.intercept_,m.coef_,resid.std(ddof=0))
    else:
        params[node]=('root',[],df[node].mean(),None,df[node].std(ddof=0))

# Intervened DAG: remove incoming edges to Y
int_edges=[(p,c) for p,c in edge_pairs if c!='Y']
pd.DataFrame({'to':[c for p,c in int_edges],'from':[p for p,c in int_edges]}).to_csv('/app/intervened_dag.csv',index=False)

# topological sort on intervened graph
nodes=cols[:]
in_deg={n:0 for n in nodes}
ch={n:[] for n in nodes}
for p,c in int_edges:
    in_deg[c]+=1; ch[p].append(c)
order=[]
q=[n for n in nodes if in_deg[n]==0]
while q:
    n=sorted(q)[0]; q.remove(n); order.append(n)
    for cc in ch[n]:
        in_deg[cc]-=1
        if in_deg[cc]==0: q.append(cc)
if len(order)!=len(nodes):
    order=nodes

# sample 10k from intervened BN
rng=np.random.default_rng(0)
out=pd.DataFrame(index=range(10000),columns=cols,dtype=float)
for node in order:
    if node=='Y':
        out[node]=0.0
        continue
    kind,ps,intercept,coef,sigma=params[node]
    if ps:
        mu=intercept+out[ps].values.dot(np.array(coef))
    else:
        mu=np.full(10000,intercept)
    out[node]=mu+rng.normal(0,sigma,10000)
out=out[cols]
out.to_csv('/app/final_bn_sample.csv',index=False)
print('done', edge_pairs)
